export function numbers177(controls,doc){for(let i=0;i<CAB_KEYS177.length;i++){const g=controls.get(CAB_KEYS177[i]);if(!g||g.userData.number177)continue;const c=doc.createElement('canvas');c.width=c.height=128;const x=c.getContext?.('2d');if(!x?.fillText)continue;x.fillStyle='#101c25';x.beginPath();x.arc(64,64,54,0,Math.PI*2);x.fill();x.strokeStyle='#e6c691';x.lineWidth=5;x.stroke();x.fillStyle='#ffffff';x.font='bold 82px Arial';x.textAlign='center';x.textBaseline='middle';x.fillText(String(i+1),64,67);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const label=new T.Sprite(new T.SpriteMaterial({map:texture,depthTest:false,toneMapped:false}));label.name='Número mando '+(i+1);label.scale.set(.060,.060,1);label.position.set(0,.075,0);label.renderOrder=12;label.raycast=()=>{};g.add(label);g.userData.number177=true;}}
export function legend177(x){x.fillStyle='#d6e7d7';x.textAlign='left';x.font='bold 22px monospace';x.fillText('MANDOS  /  TECLAS 1–6',355,33);x.font='23px sans-serif';for(let i=0;i<CAB_NAMES177.length;i++)x.fillText((i+1)+'  '+CAB_NAMES177[i],355,70+i*36);}
export function sideScreens177(board,doc){board.updateMatrixWorld(true);const items=[];board.traverse(o=>{if(o.isMesh&&/^Fondo_indicador149/.test(o.name))items.push(o);if(o.isMesh&&/^Rotulacion149_(CABINA|OPERADOR|PUERTAS|SUPERVISION)/.test(o.name))o.visible=false;});for(const o of items){const c=doc.createElement('canvas');c.width=c.height=1024;const x=c.getContext?.('2d');if(!x?.fillText)continue;x.scale?.(2,2);const start=o.getWorldPosition(new T.Vector3()).x<0?0:3;x.fillStyle='#10221f';x.fillRect(0,0,512,512);x.fillStyle='#d9ecd8';x.textAlign='left';x.font='bold 38px Arial';x.fillText('MANDOS '+(start+1)+'–'+(start+3),22,48);for(let j=0;j<3;j++){x.font='bold 60px Arial';x.fillStyle='#f2d4a1';x.fillText(String(start+j+1),22,135+j*130);x.font='bold 48px Arial';x.fillStyle='#d9ecd8';const text=CAB_NAMES177[start+j],split=text.lastIndexOf(' ');if(split<0)x.fillText(text,95,140+j*130);else{x.fillText(text.slice(0,split),95,113+j*130);x.fillText(text.slice(split+1),95,165+j*130);}}const map=crisp180(new T.CanvasTexture(c));o.geometry.computeBoundingBox();const b=o.geometry.boundingBox,size=b.getSize(new T.Vector3()),plane=new T.Mesh(new T.PlaneGeometry(size.x*.96,size.y*.96),new T.MeshBasicMaterial({map,toneMapped:false}));plane.position.copy(b.getCenter(new T.Vector3()));plane.position.z=b.max.z+.001;plane.userData.sideLegend177=true;plane.userData.firstNumber177=start+1;plane.raycast=()=>{};o.add(plane);}}
